internal static class AuraAnimationTests {
 static int checks;
 static void Check(bool value,string name){checks++;if(!value)throw new Exception(name);}
 static Dictionary<string,object> Map(params object[] values){var map=new Dictionary<string,object>();for(int i=0;i<values.Length;i+=2)map[(string)values[i]]=values[i+1];return map;}
 static AuraSyncCommandReply Reply(bool confirmed=true){return new AuraSyncCommandReply{Ok=true,Accepted=true,WriteAttempted=true,WriteConfirmed=confirmed};}
 static AuraAnimationBinding Direct(string id="native-synthetic-board"){var state=Map("id",id,"backend","native-hid","vendorId","0B05","productId","1AA6","controllerFamily","motherboard","zoneCount",4,"leds",9,"effects",new[]{"static"});var target=AuraSyncCoordinator.Direct(state,"Synthetic motherboard",DateTime.UtcNow);var session=new object();target.WorkerSession=session;target.ConnectionGeneration=4;return new AuraAnimationBinding{Target=target,WorkerSession=session,ConnectionGeneration=4};}
 static AuraAnimationBinding Peripheral(string kind="mouse"){int pid=kind=="mouse"?7548:7588;var lighting=Map("currentMode",0,"recipeMode",0,"area",0,"brightness",100,"speed",17,"direction",0,"random",false,"color",new[]{4,8,16},"flags",0,"secondaryColor",new[]{0,0,0},"backgroundColor",new[]{0,0,0});var state=Map("kind",kind,"pid",pid,"deviceId","hid-synthetic-"+kind,"model","Synthetic "+kind,"online",true,"readbackConfirmed",true,"setCapabilities",new[]{"staticLighting","lightingSoftwareMode"},"snapshot",Map("lighting",lighting,"uniformStaticLightingProtocolAvailable",true,"uniformStaticLightingReady",true,"lightingSoftwareMode",false,"windowsLightingEnabled",false));var target=AuraSyncCoordinator.Gear(state,DateTime.UtcNow);var session=new object();target.WorkerSession=session;target.ConnectionGeneration=4;return new AuraAnimationBinding{Target=target,WorkerSession=session,ConnectionGeneration=4};}
 static AuraAnimationBinding Headset(){var state=Map("kind","headset","pid",7489,"deviceId","hid-synthetic-headset","model","Synthetic headset","online",true,"readbackConfirmed",true,"setCapabilities",new[]{"brightness","lightingEffect","lightingColor","lightingEnabled"},"snapshot",Map("brightnessRaw",50,"lightingEffectCode",2,"color",new[]{4,8,16},"lightingEnabled",true,"auraEnabled",false));var target=AuraSyncCoordinator.Gear(state,DateTime.UtcNow);var session=new object();target.WorkerSession=session;target.ConnectionGeneration=4;return new AuraAnimationBinding{Target=target,WorkerSession=session,ConnectionGeneration=4};}
 static AuraAnimationBinding ScopedHeadset(){var state=Map("kind","headset","pid",7489,"deviceId","hid-synthetic-headset-scope","model","Synthetic headset scope","transport","rf","controlScope","headsetLightingOnly","online",true,"readbackConfirmed",true,"readCapabilities",new[]{"lighting","lightingEnabled","auraEnabled"},"setCapabilities",new[]{"staticLighting"},"snapshot",Map("modelPid",7489,"brightnessRaw",47,"lightingEffectCode",0,"color",new[]{4,8,16},"lightingEnabled",false,"auraEnabled",false,"headsetLightingProtocolPrepared",true,"headsetLightingFieldsConfirmed",true,"uniformStaticLightingProtocolAvailable",true,"uniformStaticLightingReady",true));var target=AuraSyncCoordinator.Gear(state,DateTime.UtcNow);var session=new object();target.WorkerSession=session;target.ConnectionGeneration=4;return new AuraAnimationBinding{Target=target,WorkerSession=session,ConnectionGeneration=4};}
 static Task<AuraAnimationBinding> Fresh(AuraAnimationBinding value){return Task.FromResult(value);}
 static Task Pause(int milliseconds,CancellationToken token){return Task.FromResult(0);}
 static void Rejected(Action call,string name){bool rejected=false;try{call();}catch(ArgumentException){rejected=true;}catch(InvalidOperationException){rejected=true;}Check(rejected,name);}
 static string Rgb(AuraSyncCommand command){if(command.Backend=="direct")return (string)command.Request["color"];if(command.Setting=="lightingColor")return "#"+String.Concat(((int[])command.Request["value"]).Select(v=>v.ToString("X2")));var value=command.Request["value"] as Dictionary<string,object>;return value==null?null:"#"+String.Concat(((int[])value["color"]).Select(v=>v.ToString("X2")));}
 static void Phase(){
  var options=new AuraAnimationOptions{Effect="breathe",Color="#804020",Brightness=50,PeriodSeconds=4};Check(AuraAnimationPhase.Sample(options,0)=="#402010","breathe maximum respects uniform brightness");Check(AuraAnimationPhase.Sample(options,1000)=="#201008","breathe quarter cycle is deterministic");Check(AuraAnimationPhase.Sample(options,2000)=="#000000","breathe midpoint is black");Check(AuraAnimationPhase.Sample(options,4000)==AuraAnimationPhase.Sample(options,0),"breathe period repeats exactly");options.Effect="flash";Check(AuraAnimationPhase.Sample(options,1999)=="#402010"&&AuraAnimationPhase.Sample(options,2000)=="#000000","flash edge uses one shared clock");options.Effect="cycle";options.PeriodSeconds=6;options.Brightness=100;var colors=new[]{"#FF0000","#FFFF00","#00FF00","#00FFFF","#0000FF","#FF00FF"};for(int i=0;i<colors.Length;i++)Check(AuraAnimationPhase.Sample(options,i*1000)==colors[i],"RGB hue sector "+i);Check(AuraAnimationPhase.Sample(options,6000)==colors[0],"cycle wraps without native spectrum mode");options.Brightness=0;foreach(long t in new long[]{0,1,1500,999999,Int64.MaxValue})Check(AuraAnimationPhase.Sample(options,t)=="#000000","valid zero remains black");foreach(string effect in new[]{"rainbow","reactive","music","stars","smart","ai",null}){options.Effect=effect;Rejected(()=>options.Validate(),"unsupported spatial/event effect never becomes enabled");}options.Effect="breathe";foreach(double value in new[]{Double.NaN,Double.PositiveInfinity,0.0,0.99,60.01}){options.PeriodSeconds=value;Rejected(()=>options.Validate(),"invalid animation period before callbacks");}options.PeriodSeconds=6;foreach(double value in new[]{Double.NaN,Double.NegativeInfinity,0.0,0.19,5.01}){options.FramesPerSecond=value;Rejected(()=>options.Validate(),"invalid bounded frequency");}options.FramesPerSecond=2;options.Color="#notRGB";Rejected(()=>options.Validate(),"invalid RGB");options.Color="#FFFFFF";options.Brightness=101;Rejected(()=>options.Validate(),"invalid brightness");options.Brightness=100;Rejected(()=>AuraAnimationPhase.Sample(options,-1),"negative clock rejects");
 }
 static void Commands(){foreach(var binding in new[]{Direct(),Peripheral(),Peripheral("keyboard"),Headset()}){var initial=AuraAnimationController.FrameCommands(binding,"#123456",true);Check(initial.Length>0&&initial.All(c=>Object.ReferenceEquals(c.ExpectedSession,binding.WorkerSession)&&c.ConnectionGeneration==4&&c.IsAnimationFrame),"every command carries immutable session/generation identity");Check(initial.All(c=>c.Backend!="direct"||(string)c.Request["effect"]=="static"),"animation never delegates native unsynchronized effects");if(binding.Target.Kind=="mouse"||binding.Target.Kind=="keyboard")Check(initial.Length==1&&(string)initial[0].Request["op"]=="lightingSet"&&initial[0].Setting=="staticLighting","scoped static writer for every peripheral frame");if(binding.Target.Kind=="headset"){Check(initial.Select(c=>c.Setting).SequenceEqual(new[]{"brightness","lightingEffect","lightingColor"}),"headset initial preparation preserves explicit order");Check(initial.All(c=>(bool)c.Request["requireLightingOwnership"]),"headset writer requires fresh native ownership guard");var frame=AuraAnimationController.FrameCommands(binding,"#123456",false);Check(frame.Length==1&&frame[0].Setting=="lightingColor"&&Rgb(frame[0])=="#123456","headset later frames do not rewrite brightness/effect");}}
  var headsetFrame=AuraAnimationController.FrameCommands(Headset(),"#123456",false).Single();Check((bool)headsetFrame.Request["requireUniformStaticLighting"],"fresh headset frame must preserve actual uniform static mode/brightness/enable state");var noSession=Direct();noSession.WorkerSession=null;Rejected(()=>AuraAnimationController.FrameCommands(noSession,"#123456",true),"worker binding absent rejects before send");var future=Direct();future.Target=AuraSyncCoordinator.Identified(Map("deviceId","future","present",true),DateTime.UtcNow);Rejected(()=>AuraAnimationController.FrameCommands(future,"#123456",true),"discovery is never animation capability");var fan=Direct();fan.Target=AuraSyncCoordinator.Fan(Map("readbackConfirmed",true,"fanCounts",new[]{1,1,1,1}),DateTime.UtcNow);Rejected(()=>AuraAnimationController.FrameCommands(fan,"#123456",true),"draft SDK fan counts are never topology");
 }
 static async Task Scheduling(){
  long now=0;int reads=0,writes=0,gates=0;var events=new List<string>();var frames=new List<string>();var targets=new[]{Direct(),Headset()};var controller=new AuraAnimationController(()=>now,Pause);Check(!controller.Active&&controller.Report.State=="idle","constructor has no work");bool ready=await controller.PrepareAsync(targets,new AuraAnimationOptions(),b=>{reads++;events.Add("read");return Fresh(b);},c=>{writes++;events.Add("write");var rgb=Rgb(c);if(rgb!=null)frames.Add(rgb);now+=100;return Task.FromResult(Reply(c.Backend!="direct"));},()=>gates++,b=>true);Check(ready&&reads==2&&writes==0&&controller.Active,"complete all-target preflight is read-only");await controller.TickAsync();Check(events.Take(2).SequenceEqual(new[]{"read","read"})&&writes==4&&gates==4,"permission is checked for each initial command");Check(frames.Count==2&&frames.All(c=>c=="#FF466A"),"slow transports receive the same sampled phase color");Check(controller.Report.Frames==1&&controller.Report.Commands==4&&controller.Report.LastDispatchSkewMilliseconds==300&&controller.Report.LastTransactionMilliseconds==400,"reports actual submission skew without claiming hardware simultaneity");Check(!controller.Report.AllLastFrameReadbackConfirmed&&controller.Report.AnyWriteAttempted,"direct output acceptance is not a physical readback");now=899;await controller.TickAsync();Check(writes==4,"rate limit counts from completion, preventing queued catchup frames");now=900;frames.Clear();await controller.TickAsync();Check(writes==6&&frames.Count==2&&frames[0]==frames[1]&&controller.Report.Frames==2,"later tick only submits current uniform color");Check(Math.Abs(controller.Report.ObservedFramesPerSecond-1000.0/700)<0.0001,"observed rate includes transport latency and idle interval");controller.RequestStop();await controller.TickAsync();Check(writes==6&&!controller.Active,"explicit stop never writes black/default/recovery frames");
  now=0;writes=0;var black=new AuraAnimationController(()=>now,Pause);await black.PrepareAsync(new[]{Direct()},new AuraAnimationOptions{Brightness=0},Fresh,c=>{writes++;return Task.FromResult(Reply(false));},()=>{},b=>true);await black.TickAsync();now=500;await black.TickAsync();Check(writes==1&&black.Report.SkippedFrames==1,"unchanged black frame is coalesced without I/O");black.RequestStop();
  now=0;writes=0;var blocked=new AuraAnimationController(()=>now,Pause);await blocked.PrepareAsync(new[]{Direct()},new AuraAnimationOptions(),Fresh,c=>{writes++;return Task.FromResult(Reply());},()=>{throw new InvalidOperationException("revoked");},b=>true);await blocked.TickAsync();Check(writes==0&&blocked.Report.State=="faulted","policy revocation before transport sends nothing");now=10000;await blocked.TickAsync();Check(writes==0,"fault is never retried by later timers");
  now=0;writes=0;var revoked=new AuraAnimationController(()=>now,Pause);await revoked.PrepareAsync(new[]{Direct(),Peripheral()},new AuraAnimationOptions(),Fresh,c=>{writes++;return Task.FromResult(Reply());},()=>{if(writes==1)throw new InvalidOperationException("revoked");},b=>true);await revoked.TickAsync();Check(writes==1&&revoked.Report.State=="faulted","policy revocation midway stops remaining group targets");
  now=0;writes=0;long generation=4;var stale=new AuraAnimationController(()=>now,Pause);await stale.PrepareAsync(new[]{Direct(),Peripheral()},new AuraAnimationOptions(),Fresh,c=>{writes++;generation++;return Task.FromResult(Reply());},()=>{},b=>b.ConnectionGeneration==generation);await stale.TickAsync();Check(writes==1&&stale.Report.State=="faulted","hotplug during output prevents another target command");await stale.TickAsync();Check(writes==1,"no retry or rebound to changed generation");
  now=0;writes=0;var uncertain=new AuraAnimationController(()=>now,Pause);await uncertain.PrepareAsync(new[]{Peripheral(),Direct()},new AuraAnimationOptions(),Fresh,c=>{writes++;return Task.FromResult(Reply(false));},()=>{},b=>true);await uncertain.TickAsync();Check(writes==1&&uncertain.Report.State=="faulted"&&uncertain.Report.AnyWriteAttempted,"unconfirmed Gear output stops group and retains attempted-write evidence");
  now=0;writes=0;var offline=new AuraAnimationController(()=>now,Pause);ready=await offline.PrepareAsync(new[]{Direct()},new AuraAnimationOptions(),b=>Task.FromResult<AuraAnimationBinding>(null),c=>{writes++;return Task.FromResult(Reply());},()=>{},b=>true);Check(!ready&&writes==0&&offline.Report.State=="faulted","missing fresh identity never outputs");
  now=0;writes=0;var sessionChanged=new AuraAnimationController(()=>now,Pause);ready=await sessionChanged.PrepareAsync(new[]{Direct()},new AuraAnimationOptions(),b=>Task.FromResult(new AuraAnimationBinding{Target=b.Target,WorkerSession=new object(),ConnectionGeneration=4}),c=>{writes++;return Task.FromResult(Reply());},()=>{},b=>true);Check(!ready&&writes==0,"restarted worker cannot inherit selected-device binding");
  now=0;writes=0;var error=new AuraAnimationController(()=>now,Pause);await error.PrepareAsync(new[]{Direct()},new AuraAnimationOptions(),Fresh,c=>{writes++;throw new TimeoutException("bounded failure");},()=>{},b=>true);await error.TickAsync();Check(writes==1&&error.Report.State=="faulted"&&error.Report.Error=="bounded failure","transport exception stops, reports exact failure, never retries");now=0;await error.TickAsync();Check(writes==1,"faulted controller cannot be woken by clock rewind");
  now=1000;writes=0;var backwards=new AuraAnimationController(()=>now,Pause);await backwards.PrepareAsync(new[]{Direct()},new AuraAnimationOptions(),Fresh,c=>{writes++;return Task.FromResult(Reply());},()=>{},b=>true);now=999;await backwards.TickAsync();Check(writes==0&&backwards.Report.State=="faulted","clock rewind never outputs an old phase");
  reads=0;var invalid=new AuraAnimationController(()=>0,Pause);var same=Direct();Rejected(()=>invalid.PrepareAsync(new[]{same,same},new AuraAnimationOptions(),b=>{reads++;return Fresh(b);},c=>Task.FromResult(Reply()),()=>{},b=>true).GetAwaiter().GetResult(),"duplicate target rejected before read");Check(reads==0,"invalid selection has no callbacks");
 }
 static async Task AsyncBoundaries(){
  long now=0;int writes=0;var output=new TaskCompletionSource<AuraSyncCommandReply>();var controller=new AuraAnimationController(()=>now,Pause);await controller.PrepareAsync(new[]{Direct(),Peripheral()},new AuraAnimationOptions(),Fresh,c=>{writes++;return output.Task;},()=>{},b=>true);var tick=controller.TickAsync();Check(!tick.IsCompleted&&controller.FrameInFlight&&writes==1,"one pending request remains owned by frame task");await controller.TickAsync();Check(writes==1,"new timer does not queue or overlap output");controller.RequestStop();Check(controller.Active&&controller.FrameInFlight,"stop retains active lease until in-flight response completes");output.SetResult(Reply());await tick;Check(!controller.Active&&controller.Report.State=="stopped"&&writes==1,"stop awaits request completion and suppresses remaining target writes");
  var read=new TaskCompletionSource<AuraAnimationBinding>();controller=new AuraAnimationController(()=>now,Pause);var binding=Direct();var preparation=controller.PrepareAsync(new[]{binding},new AuraAnimationOptions(),b=>read.Task,c=>{writes++;return Task.FromResult(Reply());},()=>{},b=>true);controller.RequestStop();Check(!preparation.IsCompleted&&controller.Active,"preflight cancellation retains async lifetime");read.SetResult(binding);Check(!await preparation&&!controller.Active,"cancelled preflight cannot begin animation");
  var pause=new TaskCompletionSource<bool>();int pauses=0;controller=new AuraAnimationController(()=>now,(milliseconds,token)=>{pauses++;Check(milliseconds>=200&&milliseconds<=60000,"sleep is bounded and low frequency");token.Register(()=>pause.TrySetCanceled());return pause.Task;});await controller.PrepareAsync(new[]{Direct()},new AuraAnimationOptions(),Fresh,c=>Task.FromResult(Reply(false)),()=>{},b=>true);var loop=controller.RunAsync();Check(!loop.IsCompleted&&pauses==1&&controller.Active,"scheduler sleeps instead of spinning");await controller.RunAsync();Check(pauses==1,"duplicate Run does not create another polling loop");controller.RequestStop();await loop;Check(!controller.Active&&controller.Report.State=="stopped","cancellable delay stops without hardware command");
  var pendingPause=new TaskCompletionSource<bool>();controller=new AuraAnimationController(()=>now,(milliseconds,token)=>pendingPause.Task);await controller.PrepareAsync(new[]{Direct()},new AuraAnimationOptions(),Fresh,c=>Task.FromResult(Reply(false)),()=>{},b=>true);loop=controller.RunAsync();controller.RequestStop();Rejected(()=>controller.PrepareAsync(new[]{Direct()},new AuraAnimationOptions(),Fresh,c=>Task.FromResult(Reply()),()=>{},b=>true).GetAwaiter().GetResult(),"new run cannot reuse controller while prior delay is pending");pendingPause.SetResult(true);await loop;Check(!controller.Active,"delayed cancellation task remains tracked until done");
 }
 static async Task ScopedHeadsetFrames(){
  var headset=ScopedHeadset();Check(headset.Target.CanStaticRgb,"complete raw0/LED-off scope is a prepared explicit Static1 route");
  foreach(bool initial in new[]{true,false}){var plan=AuraAnimationController.FrameCommands(headset,"#123456",initial);Check(plan.Length==1&&plan[0].Setting=="staticLighting"&&(string)plan[0].Request["op"]=="lightingSet"&&Rgb(plan[0])=="#123456","scoped headset retains its complete static transaction on every frame");Check(Object.ReferenceEquals(plan[0].ExpectedSession,headset.WorkerSession)&&plan[0].ConnectionGeneration==4&&plan[0].IsAnimationFrame&&(bool)plan[0].Request["requireLightingOwnership"],"scoped headset keeps exact original session and ownership guard");}
  long now=0;var requests=new List<AuraSyncCommand>();var options=new AuraAnimationOptions{Effect="cycle",PeriodSeconds=6};var controller=new AuraAnimationController(()=>now,Pause);Check(await controller.PrepareAsync(new[]{headset},options,Fresh,c=>{requests.Add(c);return Task.FromResult(Reply());},()=>{},b=>true),"scoped preparation sends no frame");Check(requests.Count==0,"raw0 is not automatically replaced by preflight");
  await controller.TickAsync();now=600;await controller.TickAsync();Check(requests.Count==2&&controller.Report.Frames==2&&controller.Report.Commands==2,"second scoped headset phase really sends a second request");Check(Rgb(requests[0])==AuraAnimationPhase.Sample(options,0)&&Rgb(requests[1])==AuraAnimationPhase.Sample(options,600)&&Rgb(requests[0])!=Rgb(requests[1]),"different phases are encoded as different output colors");Check((int)((Dictionary<string,object>)headset.Target.State["snapshot"])["lightingEffectCode"]==0,"frame planning never relabels the observed old raw0");controller.RequestStop();
  foreach(bool rejected in new[]{false,true}){now=0;int writes=0;controller=new AuraAnimationController(()=>now,Pause);await controller.PrepareAsync(new[]{ScopedHeadset(),Direct()},options,Fresh,c=>{writes++;return Task.FromResult(writes==3?new AuraSyncCommandReply{Ok=!rejected,Accepted=true,WriteAttempted=true,WriteConfirmed=false,Error="Synthetic partial/rejected scoped output"}:Reply());},()=>{},b=>true);await controller.TickAsync();Check(writes==2&&controller.Report.Frames==1,"initial mixed group completes one nonempty frame");now=600;await controller.TickAsync();Check(writes==3&&controller.Report.State=="faulted"&&controller.Report.Frames==1&&controller.Report.Commands==2,"partial or rejected scoped second frame stops before the remaining target and never increments completion");now=1200;await controller.TickAsync();Check(writes==3,"unconfirmed scoped output never retries or advances another phase");}
  foreach(bool nullPlan in new[]{false,true}){now=0;int writes=0;controller=new AuraAnimationController(()=>now,Pause,(b,output,initial)=>b.Target.Kind=="mouse"?(nullPlan?null:new AuraSyncCommand[0]):AuraAnimationController.FrameCommands(b,output,initial));await controller.PrepareAsync(new[]{Direct(),Peripheral()},options,Fresh,c=>{writes++;return Task.FromResult(Reply());},()=>{},b=>true);await controller.TickAsync();Check(writes==0&&controller.Report.State=="faulted"&&controller.Report.Frames==0&&!controller.Report.AllLastFrameReadbackConfirmed,"empty/null target plan fails the complete group before any output or vacuous confirmation");now=600;await controller.TickAsync();Check(writes==0,"invalid plan cannot silently recover on the next timer");}
  now=0;int laterWrites=0;controller=new AuraAnimationController(()=>now,Pause,(b,output,initial)=>initial?AuraAnimationController.FrameCommands(b,output,true):new AuraSyncCommand[0]);await controller.PrepareAsync(new[]{ScopedHeadset()},options,Fresh,c=>{laterWrites++;return Task.FromResult(Reply());},()=>{},b=>true);await controller.TickAsync();now=600;await controller.TickAsync();Check(laterWrites==1&&controller.Report.Frames==1&&controller.Report.State=="faulted","a later empty adapter plan cannot fabricate another completed or confirmed frame");
 }
 static int Main(){try{Phase();Commands();Scheduling().GetAwaiter().GetResult();AsyncBoundaries().GetAwaiter().GetResult();ScopedHeadsetFrames().GetAwaiter().GetResult();Console.WriteLine("Aura animation: "+checks+" pure checks passed; worker requests 0, hardware writes 0.");return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
